import sys
from typing import List

def find_bulkheads(C: int, N: int, points: List[List[int]]) -> List[float]:
    def get_area(x1, y1, x2, y2):
        return abs((x1 * y2) - (x2 * y1))

    def calculate_areas(points):
        areas = [0] * len(points)
        for i in range(len(points)):
            areas[i] = get_area(points[(i - 1) % len(points)][0], points[(i - 1) % len(points)][1],
                               points[i][0], points[i][1])
        return areas

    def bisect_left(areas, target):
        left, right = 0, len(areas) - 1
        while left < right:
            mid = (left + right) // 2
            if areas[mid] >= target:
                right = mid
            else:
                left = mid + 1
        return left

    def bisect_right(areas, target):
        left, right = 0, len(areas) - 1
        while left < right:
            mid = (left + right + 1) // 2
            if areas[mid] <= target:
                left = mid
            else:
                right = mid - 1
        return left

    areas = calculate_areas(points)
    total_area = sum(areas)
    M = total_area // C
    bulkheads = []

    for _ in range(M):
        avg_area = total_area / (len(bulkheads) + 2)
        left_idx = bisect_left(areas, avg_area)
        right_idx = bisect_right(areas, avg_area)
        if left_idx == right_idx:
            left_idx -= 1
        midpoint = (points[left_idx][0] + points[right_idx][0]) / 2
        bulkheads.append(midpoint)
        total_area -= areas.pop(left_idx)

    bulkheads.sort()
    return bulkheads

if __name__ == "__main__":
    C = int(input().strip())
