from sys import stdin, stdout
import math

def read_ints():
    return list(map(int, stdin.readline().split()))

def calculate_area(x1, y1, x2, y2):
    return abs((x1 * y2) - (x2 * y1))

def calculate_bulkhead_positions(C, N, vertices):
    total_area = 0
    for i in range(N):
        total_area += calculate_area(vertices[i][0], vertices[i][1], vertices[(i + 1) % N][0], vertices[(i + 1) % N][1])

    M = math.ceil(total_area / C)
    positions = []

    for i in range(M - 1):
        x1 = vertices[0][0] + (vertices[1][0] - vertices[0][0]) * (i + 1) / M
        positions.append(x1)

        # Adjust for the non-uniformity due to different heights
        adjust_factor = calculate_area(x1, vertices[0][1], x1, vertices[1][1]) / calculate_area(vertices[0][0], vertices[0][1], vertices[1][0], vertices[1][1])
        positions[-1] += (vertices[1][0] - x1) * adjust_factor

    return M, sorted(positions)

if __name__ == "__main__":
    C = read_ints()[0]
    N = read_ints()[0]
