import sys
from fractions import Fraction

def main():
    cin = sys.stdin.read
    data = cin().split()

    C = int(data[0])
    N = int(data[1])

    vertices = []
    index = 2
    for _ in range(N):
        x = int(data[index])
        y = int(data[index + 1])
        vertices.append((x, y))
        index += 2

    def polygon_area(vertices):
        n = len(vertices)
        area = 0
        for i in range(n):
            j = (i + 1) % n
            area += vertices[i][0] * vertices[j][1]
            area -= vertices[j][0] * vertices[i][1]
        return abs(area) / 2.0

    total_area = polygon_area(vertices)

    if total_area < C:
        print(0)
        exit()

    def get_x_coordinate(y, vertices):
        n = len(vertices)
        x_sum = 0
        for i in range(n):
            j = (i + 1) % n
            s = (vertices[i][1] <= y <= vertices[j][1]) or (vertices[j][1] <= y <= vertices[i][1])
            if s:
                x_sum += (vertices[j][0] + vertices[i][0]) * ((vertices[j][1] - y) * (vertices[i][1] - y)) / (vertices[i][1] - vertices[j][1])
        return x_sum / (2 * (total_area - C))

    placed_bulkheads = set()
    for v1, v2 in zip(vertices, vertices[1:] + [vertices[0]]):
        if v1[1] != v2[1]:
            for y in range(min(v1[1], v2[1]), max(v1[1], v2[1])):
                x = get_x_coordinate(y, vertices)
                if x not in placed_bulkheads:
                    placed_bulkheads.add(x)

    bulkheads_sorted = sorted(placed_bulkheads)
    M = len(bulkheads_sorted) + 1
    print(M)

    for i in range(len(bulkheads_sorted)):
        print(f"{bulkheads_sorted[i]:.6f}")

if __name__ == "__main__":
    main()
